  ($pp$Redwood Regional Park$pp$, $pp$redwood-regional$pp$, $pp$park$pp$::public.place_type, $pp$East Bay Regional Park District$pp$, 37.81, -122.165, $pp$east_bay$pp$::public.region, $pp$Oakland$pp$, $pp$off_leash_zones$pp$::public.dog_status, $pp$District-wide rule: dogs may be off leash in open space and undeveloped areas if they are in view and under voice control, and must return to leash when called. Leash (6 ft max) is required in developed areas, parking lots, picnic areas, grazing areas and for the first 200 ft of a trailhead. Dogs must be on leash in the Serpentine Prairie area (Dunn and Serpentine Prairie trails), and are not allowed in Redwood Arena or the Redwood Stream Protection Area.$pp$, $pp$This rule comes from the district-wide dogs page; this park has no park-specific rule listed there. Posted signs override.$pp$, $pp$https://ebparks.org/dogs$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-07$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, array[$pp$poison_oak$pp$, $pp$mud$pp$, $pp$cyclists$pp$]::text[], null, $pp$lots$pp$, null, 120, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-07T00:00:00.000Z$pp$::timestamptz),
