  ($pp$briones$pp$, $pp${"src":"/photos/briones.jpg","alt":"Green rolling hills along Lafayette Ridge in Briones Regional Park","credit":"Mrbilal1987 (assumed author)","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Lafayette_Ridge_-_Briones_Regional_Park_-_San_San_Francisco.jpg","license_url":null}$pp$, $pp${"trails":[],"park_wide":["Dogs must be on a leash (6 feet maximum) at all times on Tavan Trail, and on parts of Diablo View, Alhambra Creek and Orchard trails."],"sources":[{"label":"East Bay Regional Park District: Briones","url":"https://www.ebparks.org/parks/briones"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$redwood-regional$pp$, $pp${"src":"/photos/redwood-regional.jpg","alt":"Tall redwood trunks in Redwood Regional Park","credit":"Binksternet","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:RedwoodRegional.jpg","license_url":null}$pp$, $pp${"trails":[],"park_wide":["The park page says there are nearly 40 miles of trails. That is all trails, not only ones open to dogs.","The park page shows a \"Dogs Allowed\" icon but does not say which trails."],"sources":[{"label":"East Bay Regional Park District: Redwood Regional","url":"https://www.ebparks.org/parks/redwood"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$sibley$pp$, $pp${"src":"/photos/sibley.jpg","alt":"Golden hills and an extinct volcano summit at Sibley Volcanic Regional Preserve","credit":"Sarah Stierch","license":"CC0","source_url":"https://commons.wikimedia.org/wiki/File:Sibley_Volcanic_Regional_Preserve_-_Stierch_A.jpg","license_url":"https://creativecommons.org/publicdomain/zero/1.0/deed.en"}$pp$, $pp${"trails":[],"park_wide":["Dogs are permitted at Sibley, but are not allowed on the adjacent Huckleberry trails."],"sources":[{"label":"East Bay Regional Park District: Sibley","url":"https://www.ebparks.org/parks/sibley"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$fort-funston$pp$, $pp${"src":"/photos/fort-funston.jpg","alt":"Overlook at Fort Funston with a hang glider and the coastline","credit":"Viriditas","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Funston_overlook_2.jpg","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, $pp${"trails":[],"park_wide":["The NPS page says its networked trails are ideal for accessible hiking, horseback riding and dog walking.","The loop trails are paved and wheelchair-accessible; the trails down to the beach are not."],"sources":[{"label":"NPS: Fort Funston","url":"https://www.nps.gov/goga/planyourvisit/fortfunston.htm"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$crissy-field$pp$, $pp${"src":"/photos/crissy-field.jpg","alt":"Crissy Field beach with the Golden Gate Bridge in the distance","credit":"Brocken Inaglory","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Crissy_Field_beach_and_Golden_Gate_Bridge.jpg","license_url":null}$pp$, null),
  ($pp$ocean-beach$pp$, $pp${"src":"/photos/ocean-beach.jpg","alt":"Cliff House above Ocean Beach at sunset","credit":"Brocken Inaglory","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Cliff_House_from_Ocean_Beach.jpg","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, null),
  ($pp$baker-beach$pp$, $pp${"src":"/photos/baker-beach.jpg","alt":"Baker Beach at dusk with the Golden Gate Bridge in the distance","credit":"BradleyPelton","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:BakeBeachAtMidday.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, null),
  ($pp$lands-end$pp$, $pp${"src":"/photos/lands-end.jpg","alt":"Coastal trail at Lands End with the Golden Gate Bridge beyond cypress trees","credit":"Pi.1415926535","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Coastal_Trail_and_Golden_Gate_Bridge,_April_2019.JPG","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, null),
  ($pp$muir-beach$pp$, $pp${"src":"/photos/muir-beach.jpg","alt":"Muir Beach with people on the sand and houses on the hillside","credit":"Frank Schulenburg","license":"CC0","source_url":"https://commons.wikimedia.org/wiki/File:Muir_Beach_as_seen_from_the_beach,_December_2013.jpg","license_url":"https://creativecommons.org/publicdomain/zero/1.0/deed.en"}$pp$, null),
  ($pp$muir-woods$pp$, $pp${"src":"/photos/muir-woods.jpg","alt":"A dirt path through tall redwoods at Muir Woods","credit":"Matthew Dillon","license":"CC BY 2.0","source_url":"https://commons.wikimedia.org/wiki/File:Muir_Woods_National_Monument_(47879029461).jpg","license_url":"https://creativecommons.org/licenses/by/2.0"}$pp$, null),
  ($pp$pulgas-ridge$pp$, $pp${"src":"/photos/pulgas-ridge.jpg","alt":"San Francisco Bay seen from Pulgas Ridge Open Space Preserve","credit":"Elf","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:SanFranciscoBayFromPulgasRidge.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, $pp${"trails":[{"name":"Cordilleras Trail","miles":0.8,"dog_note":"Midpen marks all Pulgas Ridge trails \"Dogs on Leash\"."},{"name":"Dick Bishop Trail","miles":null,"dog_note":"Midpen marks all Pulgas Ridge trails \"Dogs on Leash\"."},{"name":"Dusky-footed Woodrat Trail","miles":2,"dog_note":"Midpen marks all Pulgas Ridge trails \"Dogs on Leash\"."},{"name":"Polly Geraci Trail","miles":1,"dog_note":"Midpen marks all Pulgas Ridge trails \"Dogs on Leash\"."}],"park_wide":["Dogs must be on a leash of 6 feet or less on all trails.","The preserve overview says there are six miles of trails in total.","A 17.5-acre off-leash area sits in the center of the preserve."],"sources":[{"label":"Midpen: Pulgas Ridge preserve","url":"https://www.openspace.org/preserves/pulgas-ridge"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$windy-hill$pp$, $pp${"src":"/photos/windy-hill.jpg","alt":"View from Windy Hill across the bay toward Mount Diablo","credit":"David R. Ingham","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Mount_Diablo_from_Windy_Hill.JPG","license_url":"https://creativecommons.org/licenses/by-sa/3.0/"}$pp$, $pp${"trails":[{"name":"Spring Ridge Trail","miles":null,"dog_note":"Listed as a dog-designated trail on Midpen's dog page."},{"name":"Betsy Crowder Trail","miles":null,"dog_note":"Listed as a dog-designated trail on Midpen's dog page."},{"name":"Sequoias Trail","miles":null,"dog_note":"Listed as a dog-designated trail on Midpen's dog page."},{"name":"Eagle Trail","miles":null,"dog_note":"Listed as a dog-designated trail on Midpen's dog page."},{"name":"Meadow Trail","miles":null,"dog_note":"Listed as a dog-designated trail on Midpen's dog page."},{"name":"Hamms Gulch Trail","miles":null,"dog_note":"Listed as a dog-designated trail on Midpen's dog page."},{"name":"Anniversary Trail","miles":0.6,"dog_note":"Listed as a dog-designated trail on Midpen's dog page; length from the preserve page."},{"name":"Lost Trail (between Anniversary and Hamms Gulch)","miles":null,"dog_note":"Listed as a dog-designated section on Midpen's dog page."},{"name":"Sausal Pond Loop","miles":1.6,"dog_note":"Midpen's preserve page: \"Dogs are able to use this trail, but must be kept on-leash.\""}],"park_wide":["Dogs are allowed only on designated trails, marked on the preserve map, on a leash of 6 feet or less.","Dogs are not allowed in water areas, including streams and ponds."],"sources":[{"label":"Midpen: Windy Hill preserve","url":"https://www.openspace.org/preserves/windy-hill"},{"label":"Midpen: dogs","url":"https://www.openspace.org/what-to-do/activities/dogs"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$rancho-san-antonio$pp$, $pp${"src":"/photos/rancho-san-antonio.jpg","alt":"A side canyon seen from Rhus Ridge Trail in Rancho San Antonio Open Space Preserve","credit":"Dicklyon","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:View_from_Rhus_Ridge_Trail.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, null),
  ($pp$devils-slide$pp$, $pp${"src":"/photos/devils-slide.jpg","alt":"Devil's Slide Trail curving along a steep coastal hillside","credit":"Jpesch95","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Devil%27s_Slide_Trail,_Pacifica,_California_(October_11,_2017).jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, $pp${"trails":[{"name":"Devil's Slide Trail","miles":1.3,"dog_note":"San Mateo County Parks lists it as dog-friendly, with dogs on leash."}],"park_wide":[],"sources":[{"label":"San Mateo County Parks: Devil's Slide Trail","url":"https://www.smcgov.org/parks/devils-slide-trail"},{"label":"San Mateo County Parks: dogs","url":"https://www.smcgov.org/parks/dogs-san-mateo-county-parks"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$junipero-serra$pp$, $pp${"src":"/photos/junipero-serra.jpg","alt":"A trail through twisted oak woodland in Junipero Serra County Park","credit":"Michael Fraley","license":"CC BY 2.0","source_url":"https://commons.wikimedia.org/wiki/File:Junipero_Serra_County_Park_23_(44634144730).jpg","license_url":"https://creativecommons.org/licenses/by/2.0"}$pp$, null),
  ($pp$pillar-point-bluff$pp$, $pp${"src":"/photos/pillar-point-bluff.jpg","alt":"A dirt trail across Pillar Point Bluff above the ocean","credit":"Viriditas","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Pillar_Point_Bluff_facing_southwest.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, null),
  ($pp$ring-mountain$pp$, $pp${"src":"/photos/ring-mountain.jpg","alt":"A rocky grass trail on Ring Mountain with the bay beyond","credit":"Frank Schulenburg","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:View_of_the_Tiburon_Peninsula_and_the_Bay_from_Ring_Mountain.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, null),
  ($pp$mount-tamalpais$pp$, $pp${"src":"/photos/mount-tamalpais.jpg","alt":"Wildflowers and grassy slopes at Mount Tamalpais State Park","credit":"Oscar Vasquez / California Department of Parks and Recreation","license":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Mount_Tamalpais_State_Park.jpg","license_url":null}$pp$, null)
) as v (slug, photo, dog_trails)
where p.slug = v.slug;

insert into public.place_rule_history (place_id, previous_status, new_status, changed_on, source_url, note)
select p.id, v.previous_status::public.dog_status, v.new_status::public.dog_status, v.changed_on, v.source_url, v.note
from (values
  ($pp$point-isabel$pp$, null, $pp$off_leash_ok$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://ebparks.org/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$tilden$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://ebparks.org/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$briones$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://ebparks.org/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$redwood-regional$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://ebparks.org/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$sibley$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://ebparks.org/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$fort-funston$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$crissy-field$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$ocean-beach$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$baker-beach$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$lands-end$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$muir-beach$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$muir-woods$pp$, null, $pp$no_dogs$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.nps.gov/muwo/planyourvisit/pets.htm$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$pulgas-ridge$pp$, null, $pp$off_leash_zones$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.openspace.org/what-to-do/activities/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$windy-hill$pp$, null, $pp$leash_required$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.openspace.org/what-to-do/activities/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$devils-slide$pp$, null, $pp$leash_required$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.smcgov.org/parks/dogs-san-mateo-county-parks$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$junipero-serra$pp$, null, $pp$leash_required$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.smcgov.org/parks/dogs-san-mateo-county-parks$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$)
) as v (slug, previous_status, new_status, changed_on, source_url, note)
join public.places p on p.slug = v.slug
where not exists (
  select 1 from public.place_rule_history h where h.place_id = p.id and h.changed_on = v.changed_on
);

insert into public.sunday_picks (place_id, week_start, note, sort_order)
select p.id, v.week_start, v.note, v.sort_order
from (values
  ($pp$point-isabel$pp$, $pp$2026-11-09$pp$::date, $pp$Off-leash fun by the bay. Bring a leash for the parking lot.$pp$, 0),
  ($pp$fort-funston$pp$, $pp$2026-11-09$pp$::date, $pp$Big sandy bluffs and voice-control zones. Check posted signs.$pp$, 1),
  ($pp$lands-end$pp$, $pp$2026-11-09$pp$::date, $pp$Coastal trail walk. Leashed or voice control per the park.$pp$, 2),
  ($pp$pulgas-ridge$pp$, $pp$2026-11-09$pp$::date, $pp$On-leash trails plus a marked off-leash area.$pp$, 3)
) as v (slug, week_start, note, sort_order)
join public.places p on p.slug = v.slug
on conflict (week_start, place_id) do nothing;
